// ---------------------------------------------------------------------------
// A tiny procedural sound studio. No audio files, just paper and air.
// ---------------------------------------------------------------------------

export class SoundStudio {
  constructor (settings = {}) {
    this.settings = { sfx: true, music: true, ...settings };
    this.ctx = null;
    this.master = null;
    this.sfxBus = null;
    this.musicBus = null;
    this.noiseBuffer = null;
    this.started = false;
    this.mood = 'forest';
    this._foldSrc = null;
    this._foldGain = null;
    this._foldFilter = null;
    this._musicTimer = null;
    this._pad = [];
    this._nextNote = 0;
  }

  unlock () {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.72;
      this.master.connect(this.ctx.destination);

      this.sfxBus = this.ctx.createGain();
      this.sfxBus.gain.value = this.settings.sfx ? 0.9 : 0;
      this.sfxBus.connect(this.master);

      this.musicBus = this.ctx.createGain();
      this.musicBus.gain.value = this.settings.music ? 0.55 : 0;
      this.musicBus.connect(this.master);

      const len = Math.floor(this.ctx.sampleRate * 2);
      const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      let last = 0;
      for (let i = 0; i < len; i++) {
        const white = Math.random() * 2 - 1;
        last = last * 0.7 + white * 0.3;
        data[i] = last;
      }
      this.noiseBuffer = buffer;

      this.started = true;
      this._startMusic();
      this._startPad();
    } catch (e) {
      console.warn('Audio unavailable', e);
    }
  }

  setSettings (settings) {
    this.settings = { ...this.settings, ...settings };
    if (!this.ctx) return;
    this.sfxBus.gain.setTargetAtTime(this.settings.sfx ? 0.9 : 0, this.ctx.currentTime, 0.05);
    this.musicBus.gain.setTargetAtTime(this.settings.music ? 0.55 : 0, this.ctx.currentTime, 0.2);
  }

  setMood (mood) {
    this.mood = mood;
    if (!this.ctx) return;
    const roots = { forest: 196, frost: 220, city: 174.61, sky: 246.94, cosmic: 164.81 };
    const root = roots[mood] || 196;
    this._pad.forEach(({ osc, ratio }, i) => {
      osc.frequency.setTargetAtTime(root * ratio, this.ctx.currentTime, 1.1);
    });
    this._startMusic();
  }

  _startPad () {
    if (!this.ctx || this._pad.length) return;
    const roots = { forest: 196, frost: 220, city: 174.61, sky: 246.94, cosmic: 164.81 };
    const root = roots[this.mood] || 196;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 540;
    filter.Q.value = 0.4;
    const bus = this.ctx.createGain();
    bus.gain.value = 0.028;
    filter.connect(bus);
    bus.connect(this.musicBus);
    [1, 1.5, 2.01].forEach((ratio, i) => {
      const osc = this.ctx.createOscillator();
      osc.type = i === 1 ? 'triangle' : 'sine';
      osc.frequency.value = root * ratio;
      const g = this.ctx.createGain();
      g.gain.value = i === 0 ? 0.8 : 0.32;
      osc.connect(g); g.connect(filter);
      osc.start();
      this._pad.push({ osc, ratio });
    });
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.055;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 140;
    lfo.connect(lfoGain); lfoGain.connect(filter.frequency);
    lfo.start();
  }

  _startMusic () {
    if (!this.ctx) return;
    if (this._musicTimer) clearInterval(this._musicTimer);
    this._musicTimer = setInterval(() => {
      if (!this.started || !this.settings.music) return;
      if (this.ctx.state !== 'running') return;
      if (Math.random() < 0.44) this._pluck();
    }, 3200);
  }

  _pluck () {
    if (!this.ctx) return;
    const scales = {
      forest: [392, 440, 493.88, 587.33, 659.25, 783.99],
      frost: [440, 523.25, 587.33, 659.25, 783.99, 880],
      city: [349.23, 392, 440, 523.25, 587.33, 698.46],
      sky: [493.88, 587.33, 659.25, 739.99, 880, 987.77],
      cosmic: [329.63, 392, 440, 493.88, 587.33, 659.25],
    };
    const scale = scales[this.mood] || scales.forest;
    const note = scale[Math.floor(Math.random() * scale.length)];
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const delay = this.ctx.createDelay(1.2);
    const fb = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 2200;
    delay.delayTime.value = 0.38;
    fb.gain.value = 0.28;
    osc.type = 'triangle';
    osc.frequency.value = note;
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(0.055, t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 1.7);
    osc.connect(gain); gain.connect(filter); filter.connect(this.musicBus);
    filter.connect(delay); delay.connect(fb); fb.connect(delay); delay.connect(this.musicBus);
    osc.start(t); osc.stop(t + 1.8);
  }

  _env (node, t, a, d, peak, sustain = 0) {
    node.gain.cancelScheduledValues(t);
    node.gain.setValueAtTime(0.0001, t);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0001, peak), t + a);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0001, sustain || 0.0001), t + a + d);
  }

  tone (freq, { dur = 0.25, type = 'sine', gain = 0.12, when = 0, slide = 0, bus = null } = {}) {
    if (!this.ctx || !this.settings.sfx) return;
    const t = this.ctx.currentTime + when;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    this._env(g, t, 0.008, dur, gain);
    osc.connect(g); g.connect(bus || this.sfxBus);
    osc.start(t); osc.stop(t + dur + 0.05);
  }

  noise ({ dur = 0.3, gain = 0.1, freq = 900, q = 1.2, type = 'bandpass', when = 0, slide = 0, bus = null } = {}) {
    if (!this.ctx || !this.noiseBuffer || !this.settings.sfx) return;
    const t = this.ctx.currentTime + when;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.Q.value = q;
    if (slide) filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq + slide), t + dur);
    const g = this.ctx.createGain();
    this._env(g, t, 0.01, dur, gain);
    src.connect(filter); filter.connect(g); g.connect(bus || this.sfxBus);
    src.start(t); src.stop(t + dur + 0.05);
  }

  click () {
    this.tone(680, { dur: 0.055, type: 'triangle', gain: 0.06 });
    this.tone(980, { dur: 0.04, type: 'sine', gain: 0.03, when: 0.03 });
  }

  swish (strong = false) {
    this.noise({ dur: strong ? 0.5 : 0.3, gain: strong ? 0.12 : 0.07, freq: 1700, slide: -1100, q: 1.6 });
  }

  crease () {
    this.noise({ dur: 0.16, gain: 0.07, freq: 1300, slide: 1400, q: 2.4 });
    this.tone(430, { dur: 0.09, type: 'triangle', gain: 0.035, slide: 60 });
  }

  snap (angle = 90) {
    this.noise({ dur: 0.09, gain: 0.1, freq: 700, q: 0.8, type: 'lowpass' });
    this.tone(angle >= 170 ? 120 : 180, { dur: 0.19, type: 'sine', gain: 0.09, slide: -30 });
    if (angle >= 170) this.tone(70, { dur: 0.3, type: 'sine', gain: 0.06 });
  }

  unfold () {
    this.noise({ dur: 0.25, gain: 0.06, freq: 900, slide: 600, q: 1.2 });
  }

  step () {
    this.noise({ dur: 0.055, gain: 0.022, freq: 950, q: 1.6, type: 'bandpass' });
  }

  star () {
    const notes = [783.99, 1046.5, 1318.5, 1567.98];
    notes.forEach((n, i) => {
      this.tone(n, { dur: 0.5, type: 'sine', gain: 0.08, when: i * 0.075 });
      this.tone(n * 2, { dur: 0.3, type: 'triangle', gain: 0.025, when: i * 0.075 + 0.01 });
    });
    this.tone(392, { dur: 0.8, type: 'sine', gain: 0.04 });
  }

  portal () {
    const chord = [261.63, 329.63, 392, 523.25, 659.25];
    chord.forEach((n, i) => {
      this.tone(n, { dur: 1.2 - i * 0.06, type: 'sine', gain: 0.06, when: i * 0.035 });
      this.tone(n * 2, { dur: 0.8, type: 'triangle', gain: 0.018, when: i * 0.04 });
    });
  }

  error () {
    this.tone(150, { dur: 0.22, type: 'sawtooth', gain: 0.04, slide: -40 });
    this.tone(110, { dur: 0.3, type: 'sine', gain: 0.05 });
  }

  fall () {
    this.tone(420, { dur: 0.7, type: 'sine', gain: 0.05, slide: -320 });
    this.noise({ dur: 0.55, gain: 0.04, freq: 900, slide: -500 });
  }

  trapped () {
    this.noise({ dur: 0.7, gain: 0.08, freq: 500, slide: -350, type: 'lowpass', q: 0.7 });
    this.tone(90, { dur: 0.6, type: 'sine', gain: 0.05 });
  }

  startFold () {
    if (!this.ctx) return;
    this.stopFold();
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 520;
    filter.Q.value = 1.1;
    const g = this.ctx.createGain();
    g.gain.value = 0.0001;
    src.connect(filter); filter.connect(g); g.connect(this.sfxBus);
    src.start();
    this._foldSrc = src;
    this._foldGain = g;
    this._foldFilter = filter;
    g.gain.setTargetAtTime(0.05, this.ctx.currentTime, 0.05);
  }

  updateFold (progress) {
    if (!this.ctx || !this._foldFilter) return;
    const p = Math.max(0, Math.min(1, progress));
    this._foldFilter.frequency.setTargetAtTime(420 + p * 1500, this.ctx.currentTime, 0.05);
    this._foldGain.gain.setTargetAtTime(0.018 + p * 0.04, this.ctx.currentTime, 0.06);
  }

  stopFold () {
    if (!this.ctx || !this._foldSrc) return;
    try {
      this._foldGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.07);
      this._foldSrc.stop(this.ctx.currentTime + 0.35);
    } catch (e) {}
    this._foldSrc = null;
    this._foldGain = null;
    this._foldFilter = null;
  }
}

// ---------------------------------------------------------------------------
// Paper craft — geometry, materials, props and characters.
// ---------------------------------------------------------------------------
import * as THREE from 'three';

const UP = new THREE.Vector3(0, 1, 0);

function rng (seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function shade (hex, amount) {
  const c = new THREE.Color(hex);
  const hsl = {};
  c.getHSL(hsl);
  hsl.l = Math.max(0, Math.min(1, hsl.l + amount));
  c.setHSL(hsl.h, hsl.s, hsl.l);
  return '#' + c.getHexString();
}

// ---------------------------------------------------------------------------
// Textures
// ---------------------------------------------------------------------------
export function makePaperTexture (theme) {
  const size = 384;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const random = rng(theme.paper.length * 991 + theme.name.length * 337);

  ctx.fillStyle = theme.paper;
  ctx.fillRect(0, 0, size, size);

  // large soft stains
  for (let i = 0; i < 9; i++) {
    const x = random() * size;
    const y = random() * size;
    const r = 18 + random() * 80;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(120,95,60,${0.012 + random() * 0.02})`);
    g.addColorStop(1, 'rgba(120,95,60,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  // paper fibres
  ctx.lineWidth = 0.6;
  for (let i = 0; i < 720; i++) {
    const x = random() * size;
    const y = random() * size;
    const len = 2 + random() * 10;
    const angle = random() * Math.PI;
    ctx.strokeStyle = random() > 0.45
      ? `rgba(255,255,255,${0.04 + random() * 0.11})`
      : `rgba(90,66,36,${0.02 + random() * 0.055})`;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * len, y + Math.sin(angle) * len);
    ctx.stroke();
  }

  // tiny flecks
  for (let i = 0; i < 190; i++) {
    const x = random() * size;
    const y = random() * size;
    ctx.fillStyle = random() > 0.5
      ? `rgba(255,255,255,${0.05 + random() * 0.12})`
      : `rgba(80,58,32,${0.025 + random() * 0.07})`;
    ctx.beginPath();
    ctx.arc(x, y, 0.35 + random() * 1.1, 0, Math.PI * 2);
    ctx.fill();
  }

  // a whisper of woven grain
  ctx.globalAlpha = 0.055;
  for (let y = 0; y < size; y += 4) {
    ctx.fillStyle = y % 8 === 0 ? '#fff' : '#5a452c';
    ctx.fillRect(0, y, size, 0.5);
  }
  ctx.globalAlpha = 1;

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

export function makeGradientTexture (top, mid, bottom) {
  const canvas = document.createElement('canvas');
  canvas.width = 64; canvas.height = 512;
  const ctx = canvas.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 512);
  g.addColorStop(0, top);
  g.addColorStop(0.48, mid);
  g.addColorStop(1, bottom);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 512);
  // soft paper-cloud bands
  const random = rng(71);
  for (let i = 0; i < 26; i++) {
    const y = 30 + random() * 430;
    const h = 8 + random() * 30;
    ctx.fillStyle = `rgba(255,255,255,${0.008 + random() * 0.025})`;
    ctx.beginPath();
    ctx.ellipse(random() * 64, y, 24 + random() * 35, h, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeGlowTexture (inner = 'rgba(255,236,180,1)', outer = 'rgba(255,190,80,0)') {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, inner);
  g.addColorStop(0.22, 'rgba(255,220,140,.55)');
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

// ---------------------------------------------------------------------------
// Materials (cached per theme)
// ---------------------------------------------------------------------------
const paperCache = new Map();
const propCache = new Map();

export function paperMaterial (theme) {
  if (paperCache.has(theme.id)) return paperCache.get(theme.id);
  const map = makePaperTexture(theme);
  const mat = new THREE.MeshStandardMaterial({
    map,
    color: 0xffffff,
    roughness: 0.93,
    metalness: 0.0,
    vertexColors: true,
    side: THREE.DoubleSide,
  });
  mat.userData.edge = new THREE.Color(theme.paperEdge);
  paperCache.set(theme.id, mat);
  return mat;
}

export function solidMaterial (theme) {
  if (propCache.has(theme.id)) return propCache.get(theme.id);
  const mat = new THREE.MeshStandardMaterial({
    map: makePaperTexture(theme),
    color: 0xffffff,
    roughness: 0.94,
    metalness: 0,
    side: THREE.FrontSide,
  });
  propCache.set(theme.id, mat);
  return mat;
}

let sharedGlow = null;
export function glowTexture () {
  if (!sharedGlow) sharedGlow = makeGlowTexture();
  return sharedGlow;
}

const matCache = new Map();
function colorMat (hex, { roughness = 0.88, metalness = 0, emissive = null, emissiveIntensity = 1, transparent = false, opacity = 1 } = {}) {
  const key = `${hex}|${roughness}|${metalness}|${emissive}|${emissiveIntensity}|${transparent}|${opacity}`;
  if (matCache.has(key)) return matCache.get(key);
  const m = new THREE.MeshStandardMaterial({
    color: new THREE.Color(hex),
    roughness,
    metalness,
    emissive: emissive ? new THREE.Color(emissive) : 0x000000,
    emissiveIntensity,
    transparent,
    opacity,
    flatShading: true,
  });
  matCache.set(key, m);
  return m;
}

// ---------------------------------------------------------------------------
// Folded sheet geometry
// ---------------------------------------------------------------------------
/**
 * Build one merged mesh geometry from unit paper cells.
 * @param {Array<[number,number]>} cells [i,j] integer cell indices
 * @param {number} thickness
 */
export function buildPanelGeometry (cells, thickness = 0.14) {
  const positions = [];
  const normals = [];
  const uvs = [];
  const colors = [];
  const t = thickness / 2;
  const uvScale = 0.24;

  const push = (p, n, uv, col) => {
    positions.push(p[0], p[1], p[2]);
    normals.push(n[0], n[1], n[2]);
    uvs.push(uv[0], uv[1]);
    colors.push(col[0], col[1], col[2]);
  };
  const quad = (a, b, c, d, n, col, uvFn) => {
    const uvA = uvFn(a), uvB = uvFn(b), uvC = uvFn(c), uvD = uvFn(d);
    push(a, n, uvA, col); push(b, n, uvB, col); push(c, n, uvC, col);
    push(a, n, uvA, col); push(c, n, uvC, col); push(d, n, uvD, col);
  };
  const white = [1, 1, 1];
  const sideCol = [0.86, 0.83, 0.78];
  const bottomCol = [0.82, 0.79, 0.73];

  for (const [i, j] of cells) {
    const x0 = i, x1 = i + 1, z0 = j, z1 = j + 1;
    const yb = -t, yt = t;
    // top (+Y)
    quad([x0, yt, z0], [x0, yt, z1], [x1, yt, z1], [x1, yt, z0], [0, 1, 0], white,
      p => [p[0] * uvScale, p[2] * uvScale]);
    // bottom (-Y)
    quad([x0, yb, z1], [x0, yb, z0], [x1, yb, z0], [x1, yb, z1], [0, -1, 0], bottomCol,
      p => [p[0] * uvScale, p[2] * uvScale]);
    // +X
    quad([x1, yb, z1], [x1, yb, z0], [x1, yt, z0], [x1, yt, z1], [1, 0, 0], sideCol,
      p => [p[2] * uvScale, p[1] * uvScale]);
    // -X
    quad([x0, yb, z0], [x0, yb, z1], [x0, yt, z1], [x0, yt, z0], [-1, 0, 0], sideCol,
      p => [p[2] * uvScale, p[1] * uvScale]);
    // +Z
    quad([x0, yb, z1], [x1, yb, z1], [x1, yt, z1], [x0, yt, z1], [0, 0, 1], sideCol,
      p => [p[0] * uvScale, p[1] * uvScale]);
    // -Z
    quad([x1, yb, z0], [x0, yb, z0], [x0, yt, z0], [x1, yt, z0], [0, 0, -1], sideCol,
      p => [p[0] * uvScale, p[1] * uvScale]);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.computeBoundingSphere();
  return geo;
}

export function createPanelMesh (panel, theme) {
  const geo = buildPanelGeometry(panel.cells, 0.14);
  const mesh = new THREE.Mesh(geo, paperMaterial(theme));
  mesh.receiveShadow = true;
  mesh.castShadow = true;
  mesh.userData.panel = panel;
  return mesh;
}

export function createPaperBox (w, h, d, theme) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const mat = solidMaterial(theme).clone();
  mat.vertexColors = false;
  mat.map = mat.map.clone();
  mat.map.needsUpdate = true;
  mat.map.repeat.set(Math.max(1, w * 0.32), Math.max(1, d * 0.32));
  mat.side = THREE.FrontSide;
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  mesh.castShadow = true;
  // paper edge trim
  const edge = new THREE.LineSegments(
    new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: theme.paperEdge, transparent: true, opacity: 0.65 })
  );
  edge.scale.setScalar(1.001);
  mesh.add(edge);
  return mesh;
}

// ---------------------------------------------------------------------------
// Crease guides
// ---------------------------------------------------------------------------
export function makeCreaseLine (length, axis, color = 0xe1b45b) {
  // dashed glowing line built from tiny quads
  const group = new THREE.Group();
  const dashCount = Math.max(4, Math.floor(length / 0.42));
  const geo = new THREE.PlaneGeometry(0.24, 0.07);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false });
  const inst = new THREE.InstancedMesh(geo, mat, dashCount);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const scale = new THREE.Vector3(1, 1, 1);
  for (let i = 0; i < dashCount; i++) {
    const p = -length / 2 + (i + 0.5) * (length / dashCount);
    m.compose(new THREE.Vector3(axis === 'x' ? 0 : p, 0, axis === 'x' ? p : 0), q, scale);
    inst.setMatrixAt(i, m);
  }
  inst.rotation.x = -Math.PI / 2;
  group.add(inst);
  const glow = new THREE.Mesh(
    new THREE.PlaneGeometry(axis === 'x' ? 0.55 : length, axis === 'x' ? length : 0.55),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.09, side: THREE.DoubleSide, depthWrite: false })
  );
  glow.rotation.x = -Math.PI / 2;
  group.add(glow);
  group.userData.inst = inst;
  group.userData.glow = glow;
  return group;
}

export function makeHinge (axis, length, y) {
  const g = new THREE.Group();
  const gold = colorMat('#c99a44', { metalness: 0.45, roughness: 0.38 });
  const cyl = new THREE.CylinderGeometry(0.055, 0.055, 0.28, 8);
  const ring = new THREE.TorusGeometry(0.105, 0.025, 6, 14);
  for (let i = 0; i < 3; i++) {
    const c = new THREE.Mesh(cyl, gold);
    const r = new THREE.Mesh(ring, gold);
    const t = -length / 2 + 0.35 + i * (length - 0.7) / 2;
    if (axis === 'x') {
      c.rotation.x = Math.PI / 2;
      c.position.set(0, 0, t);
      r.rotation.y = Math.PI / 2;
      r.position.set(0, 0.07, t);
    } else {
      c.rotation.z = Math.PI / 2;
      c.position.set(t, 0, 0);
      r.rotation.x = Math.PI / 2;
      r.position.set(t, 0.07, 0);
    }
    c.castShadow = true;
    g.add(c, r);
  }
  g.position.y = y;
  return g;
}

// ---------------------------------------------------------------------------
// Stars, exit and portals
// ---------------------------------------------------------------------------
function starShape (outer = 0.34, inner = 0.15) {
  const shape = new THREE.Shape();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = -Math.PI / 2 + i * Math.PI / 5;
    const x = Math.cos(a) * r;
    const y = Math.sin(a) * r;
    if (i === 0) shape.moveTo(x, y); else shape.lineTo(x, y);
  }
  shape.closePath();
  return shape;
}

export function createStar (color = 0xe3b14f) {
  const group = new THREE.Group();
  const gold = colorMat('#e2b252', { metalness: 0.55, roughness: 0.35, emissive: '#7a4d0d', emissiveIntensity: 0.35 });
  const pale = colorMat('#f6dfa2', { metalness: 0.3, roughness: 0.5, emissive: '#a97920', emissiveIntensity: 0.3 });

  const geo = new THREE.ExtrudeGeometry(starShape(0.31, 0.135), {
    depth: 0.09, bevelEnabled: true, bevelThickness: 0.035, bevelSize: 0.025, bevelSegments: 1,
  });
  geo.center();
  const star = new THREE.Mesh(geo, gold);
  star.castShadow = true;
  group.add(star);

  const small = new THREE.Mesh(new THREE.OctahedronGeometry(0.075, 0), pale);
  small.position.z = 0.005;
  group.add(small);

  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture(), color: 0xffcf79, transparent: true, opacity: 0.65,
    blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  glow.scale.setScalar(1.5);
  group.add(glow);

  group.userData.spin = star;
  group.userData.glow = glow;
  return group;
}

export function createExitSeal (theme) {
