// Environment lighting factory
// ---------------------------------------------------------------------------
export function addEnvironmentLighting (scene, theme) {
  const hemi = new THREE.HemisphereLight(theme.skyTop, theme.ground, 1.25);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(theme.sun, 2.4);
  sun.position.set(...theme.sunPos);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 40;
  const s = 12;
  sun.shadow.camera.left = -s;
  sun.shadow.camera.right = s;
  sun.shadow.camera.top = s;
  sun.shadow.camera.bottom = -s;
  sun.shadow.bias = -0.0005;
  sun.shadow.normalBias = 0.02;
  scene.add(sun);
  scene.add(sun.target);
  const fill = new THREE.DirectionalLight(theme.accent2, 0.35);
  fill.position.set(-6, 5, -7);
  scene.add(fill);
  return { hemi, sun, fill };
}

