353:         new THREE.TorusGeometry(s.w * 0.72, 0.035, 6, 14),
354:         new THREE.MeshStandardMaterial({ color: theme.accent2, metalness: 0.4, roughness: 0.5 })
355:       );
356:       ring.rotation.x = Math.PI / 2;
357:       ring.position.set(s.x, s.top - 0.12, s.z);
358:       this.worldGroup.add(ring);
359:     }
360: 
361:     // --- exit --------------------------------------------------------------
362:     this.exit = null;
363:     if (world.exit) {
364:       const seal = P.createExitSeal(theme);
365:       this.worldGroup.add(seal);
366:       if (world.exit.sheet !== undefined) {
367:         const panel = this.sheetPanels[world.exit.sheet];
368:         const anchor = new THREE.Object3D();
369:         anchor.position.set(world.exit.x, 0.12, world.exit.z);
370:         panel.group.add(anchor);
371:         panel.attachments.push(anchor);
372:         this.exit = { group: seal, anchor, baseY: 0, static: false };
373:       } else {
374:         seal.position.set(world.exit.x, world.exit.y + 0.01, world.exit.z);
375:         this.exit = { group: seal, anchor: null, baseY: world.exit.y + 0.01, static: true };
376:       }
377:     }
378: 
379:     // --- collectible stars -------------------------------------------------
380:     for (const s of world.stars || []) {
381:       const star = P.createStar(theme.star);
382:       this.worldGroup.add(star);
383:       let anchor = null;
384:       let baseY = s.y || 0;
385:       if (s.sheet !== undefined) {
386:         const panel = this.sheetPanels[s.sheet];
387:         anchor = new THREE.Object3D();
388:         anchor.position.set(s.x, s.bottom ? -0.24 : 0.55, s.z);
389:         panel.group.add(anchor);
390:         panel.attachments.push(anchor);
391:       } else {
392:         star.position.set(s.x, s.y, s.z);
393:       }
394:       this.stars.push({ group: star, anchor, baseY, collected: false, seed: Math.random() * 9, spin: Math.random() * 6 });
395:     }
396: 
397:     // --- enemies -----------------------------------------------------------
398:     for (const e of world.enemy || []) {
399:       const beetle = this._makeBeetle();
400:       beetle.position.set(e.x, e.y, e.z);
401:       this.worldGroup.add(beetle);
402:       this.enemies.push({ obj: beetle, ...e, phase: Math.random() * 6, base: e.x, dir: 1 });
403:     }
404: 
405:     // --- decorations -------------------------------------------------------
406:     this._buildDecor();
407:     this._buildAtmosphere();
408:     this._buildPlayer();
409:     this._computeBounds();
410:     this._frameLevel();
411: 
412:     this.mode = 'game';
413:     this.emit('levelstart', {
414:       index,
415:       level: this.level,
416:       totalStars: this.totalStars,
417:       tutorial: !!this.level.tutorial,
418:     });
419: 
420:     // immediately ground the player
421:     const g = this._groundAt(this.player.pos.x, this.player.pos.z, 4);
422:     if (g) {
423:       this.player.pos.y = g.y;
424:       this.player.groundY = g.y;
425:       this.player.grounded = true;
426:       if (g.mesh?.userData.panel) this.player.panel = g.mesh.userData.panel;
427:     }
428: 
429:     if (this.level.tutorial) {
430:       this.showHint(0, { auto: true });
431:       this.emit('tutorial', {
432:         title: 'The world is paper',
433:         text: 'Swipe along the glowing crease to begin.',
434:       });
435:       this.emit('toast', { text: 'Swipe along the dotted crease', duration: 3400 });
436:     } else {
437:       this.emit('tutorial', {
438:         title: this.level.name,
439:         text: 'Swipe a crease. Drag a side to fold the world.',
440:       });
441:     }
442:     this.emit('hud', { stars: 0, total: this.totalStars });
443:   }
