459:   _disposeScene (scene) {
460:     if (!scene) return;
461:     scene.traverse(obj => {
462:       if (obj.geometry && !obj.geometry.userData?.shared) obj.geometry.dispose?.();
463:       if (obj.isSprite && obj.material?.map && !obj.material.map.userData?.shared) { /* shared glow texture */ }
464:     });
465:     if (scene.background && scene.background.isTexture) scene.background.dispose();
466:     scene.clear();
