469:   _buildDecor () {
470:     const world = this.level;
471:     const theme = this.theme;
472:     // edge decorations on each paper sheet, attached to the paper so they fold with it
473:     world.sheets.forEach((sheetData, si) => {
474:       const panel = this.sheetPanels[si];
475:       if (!panel) return;
476:       const hintLines = world.hints?.filter(h => h.sheet === si) || [];
477:       const random = mulberry(world.decorSeed * 17 + si * 101);
478:       const edge = new Set();
479:       for (const [i, j] of panel.cells) {
480:         const minI = sheetData.bounds.minX, maxI = sheetData.bounds.maxX - 1;
481:         const minJ = sheetData.bounds.minZ, maxJ = sheetData.bounds.maxZ - 1;
482:         if (i === minI || i === maxI || j === minJ || j === maxJ) edge.add(cellKey(i, j));
483:       }
484:       const candidates = [...edge].filter(key => {
485:         const [i, j] = key.split(',').map(Number);
486:         const cx = i + 0.5, cz = j + 0.5;
487:         if (Math.hypot(cx - world.player[0], cz - world.player[1]) < 1.35) return false;
488:         for (const h of hintLines) {
489:           const d = h.axis === 'x' ? Math.abs(cx - h.coord) : Math.abs(cz - h.coord);
490:           if (d < 1.0) return false;
491:         }
492:         for (const s of world.stars || []) {
493:           if (s.sheet === si && Math.hypot(cx - s.x, cz - s.z) < 0.8) return false;
494:         }
495:         if (world.exit?.sheet === si && Math.hypot(cx - world.exit.x, cz - world.exit.z) < 0.9) return false;
496:         return true;
497:       });
498:       // keep a few open lanes in the middle of the paper
499:       const count = Math.min(candidates.length, this.isMobile ? 6 : 9);
500:       for (let n = 0; n < count; n++) {
501:         const idx = Math.floor(random() * candidates.length);
502:         const [i, j] = candidates.splice(idx, 1)[0].split(',').map(Number);
503:         const type = theme.decorate[Math.floor(random() * theme.decorate.length)];
504:         const prop = P.createProp(type, theme, 0.55 + random() * 0.5);
505:         prop.position.set(i + 0.5 + (random() - 0.5) * 0.3, 0.075, j + 0.5 + (random() - 0.5) * 0.3);
506:         prop.rotation.y = random() * Math.PI * 2;
507:         panel.group.add(prop);
508:         panel.attachments.push(prop);
509:       }
510:     });
511: 
512:     // decorations on static platforms
513:     for (const d of world.platformDecor || []) {
514:       const prop = P.createProp(d.type, theme, d.scale || 0.8);
515:       prop.position.set(d.x, d.top, d.z);
516:       prop.rotation.y = d.rot || 0;
517:       this.worldGroup.add(prop);
518:     }
519:   }
