521:   _buildAtmosphere () {
522:     const theme = this.theme;
523:     const b = this._roughBounds();
524:     const center = b.getCenter(new THREE.Vector3());
525:     const size = b.getSize(new THREE.Vector3());
526:     const motes = P.createParticles(this.isMobile ? 70 : 130, theme.motes, 0.06, [Math.max(9, size.x), 6, Math.max(7, size.z)], 0.55);
527:     motes.position.set(center.x, 0.4, center.z);
528:     this.worldGroup.add(motes);
529:     this.motes.push({ obj: motes, base: motes.geometry.attributes.position.array.slice(), speed: 0.2 });
530: 
531:     // slow paper snow / petals / cosmic dust
532:     const flakeCount = this.level.theme === 'frost' ? (this.isMobile ? 60 : 110) : (this.isMobile ? 22 : 42);
533:     const flakeColor = this.level.theme === 'frost' ? 0xffffff : this.level.theme === 'cosmic' ? 0xffe7a8 : this.level.theme === 'forest' ? 0xf3d79b : 0xdcc9a4;
534:     const flakes = P.createParticles(flakeCount, flakeColor, this.level.theme === 'frost' ? 0.055 : 0.04, [Math.max(9, size.x), 8, Math.max(7, size.z)], 0.42);
535:     flakes.position.set(center.x, 2.5, center.z);
536:     this.worldGroup.add(flakes);
537:     this.motes.push({ obj: flakes, base: flakes.geometry.attributes.position.array.slice(), speed: 0.6, falling: true });
538: 
539:     // floating paper bits
540:     for (let i = 0; i < (this.isMobile ? 8 : 16); i++) {
541:       const geo = new THREE.PlaneGeometry(0.12 + Math.random() * 0.18, 0.08 + Math.random() * 0.12);
542:       const mat = new THREE.MeshStandardMaterial({
543:         color: theme.paper, roughness: 0.92, side: THREE.DoubleSide,
544:         transparent: true, opacity: 0.72,
545:       });
546:       const bit = new THREE.Mesh(geo, mat);
547:       bit.position.set(center.x + (Math.random() - 0.5) * size.x * 1.2, 0.6 + Math.random() * 4.2, center.z + (Math.random() - 0.5) * size.z * 1.2);
548:       bit.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
549:       this.worldGroup.add(bit);
550:       this.paperBits.push({ obj: bit, phase: Math.random() * 8, spin: (Math.random() - 0.5) * 0.8, baseY: bit.position.y, amp: 0.15 + Math.random() * 0.25 });
551:     }
552: 
553:     // clouds around the island
554:     const cloudCount = this.level.theme === 'sky' ? 7 : this.level.theme === 'cosmic' ? 2 : 3;
555:     for (let i = 0; i < cloudCount; i++) {
556:       const cloud = P.createCloud(0.5 + Math.random() * 0.8, 0.34);
557:       const angle = (i / cloudCount) * Math.PI * 2 + Math.random();
558:       const rad = Math.max(size.x, size.z) * 0.7 + 1.5;
559:       cloud.position.set(center.x + Math.cos(angle) * rad, -1.4 + Math.random() * 2.8, center.z + Math.sin(angle) * rad);
560:       this.worldGroup.add(cloud);
561:       this.clouds.push({ obj: cloud, baseX: cloud.position.x, speed: 0.04 + Math.random() * 0.04, phase: Math.random() * 6 });
562:     }
563: 
564:     // background small islands / folded debris
565:     const islets = this.level.theme === 'sky' || this.level.theme === 'cosmic' ? 5 : 3;
566:     for (let i = 0; i < islets; i++) {
567:       const angle = (i / islets) * Math.PI * 2 + 1.2;
568:       const radius = Math.max(size.x, size.z) * 0.75 + 2.2;
569:       const isl = P.createIsland(theme, 0.35 + Math.random() * 0.55, 0.18);
570:       isl.position.set(center.x + Math.cos(angle) * radius, -1.2 + Math.random() * 3.6, center.z + Math.sin(angle) * radius);
571:       isl.rotation.y = Math.random() * 6;
572:       this.worldGroup.add(isl);
573:       const type = theme.decorate[i % theme.decorate.length];
574:       const prop = P.createProp(type, theme, 0.3 + Math.random() * 0.25);
575:       prop.position.copy(isl.position);
576:       prop.position.y += 0.02;
577:       this.worldGroup.add(prop);
578:       this.clouds.push({ obj: isl, baseY: isl.position.y, phase: Math.random() * 9, islet: true, prop });
579:     }
580: 
581:     // cranes drifting through the scene
582:     for (let i = 0; i < 3; i++) {
583:       const crane = P.createCrane(theme);
584:       crane.scale.setScalar(0.8);
585:       crane.position.set(center.x, 2.2 + i * 0.8, center.z);
586:       this.worldGroup.add(crane);
587:       this.cranes.push({ obj: crane, phase: Math.random() * 8, radius: 3 + i * 0.6, height: 2.4 + i * 0.5, speed: 0.08 + i * 0.02 });
588:     }
589: 
590:     if (this.level.theme === 'cosmic') {
591:       const starGeo = new THREE.BufferGeometry();
592:       const arr = [];
593:       for (let i = 0; i < 180; i++) {
594:         const a = Math.random() * Math.PI * 2;
595:         const r = 8 + Math.random() * 16;
596:         arr.push(center.x + Math.cos(a) * r, 2 + Math.random() * 12, center.z + Math.sin(a) * r);
597:       }
598:       starGeo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
599:       const starPoints = new THREE.Points(starGeo, new THREE.PointsMaterial({
600:         color: 0xffe1a0, size: 0.12, transparent: true, opacity: 0.85,
601:         blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
602:       }));
603:       this.worldGroup.add(starPoints);
604:       this.backStars = starPoints;
605:     }
606:   }
