608:   _makeBeetle () {
609:     const theme = this.theme;
610:     const g = new THREE.Group();
611:     const bodyMat = new THREE.MeshStandardMaterial({
612:       color: new THREE.Color(theme.accent), roughness: 0.6, metalness: 0.15,
613:       emissive: new THREE.Color(theme.accent), emissiveIntensity: 0.08, flatShading: true,
614:     });
615:     const shellMat = new THREE.MeshStandardMaterial({
616:       color: new THREE.Color(theme.accent2), roughness: 0.55, metalness: 0.1,
617:       emissive: new THREE.Color(theme.accent2), emissiveIntensity: 0.1, flatShading: true,
618:     });
619:     const body = new THREE.Mesh(new THREE.OctahedronGeometry(0.22, 0), bodyMat);
620:     body.scale.set(1, 0.55, 1.4);
621:     body.position.y = 0.2;
622:     body.castShadow = true;
623:     g.add(body);
624:     const shell = new THREE.Mesh(new THREE.SphereGeometry(0.2, 6, 4, 0, Math.PI * 2, 0, Math.PI / 2), shellMat);
625:     shell.scale.set(1, 0.7, 1.35);
626:     shell.position.y = 0.23;
627:     shell.castShadow = true;
628:     g.add(shell);
629:     const head = new THREE.Mesh(new THREE.OctahedronGeometry(0.1, 0), bodyMat);
630:     head.position.set(0, 0.18, 0.27);
631:     g.add(head);
632:     const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffd77b });
633:     for (const side of [-1, 1]) {
634:       const eye = new THREE.Mesh(new THREE.SphereGeometry(0.025, 5, 4), eyeMat);
635:       eye.position.set(side * 0.06, 0.2, 0.34);
636:       g.add(eye);
637:     }
638:     const legs = [];
639:     for (let i = 0; i < 3; i++) {
640:       for (const side of [-1, 1]) {
641:         const leg = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.24, 0.04), bodyMat);
642:         leg.position.set(side * 0.24, 0.1, -0.16 + i * 0.16);
643:         leg.rotation.z = side * 0.75;
644:         g.add(leg);
645:         legs.push(leg);
646:       }
647:     }
648:     g.userData.legs = legs;
649:     return g;
650:   }
