676:   _computeBounds () {
677:     const box = this._roughBounds();
678:     box.min.y = Math.min(box.min.y, -0.8);
679:     box.max.y = Math.max(box.max.y, 4.2);
680:     box.expandByScalar(0.55);
681:     this.levelBounds = box;
682:   }
683: 
684:   _roughBounds () {
685:     const box = new THREE.Box3();
686:     const addPoint = (x, y, z) => box.expandByPoint(new THREE.Vector3(x, y, z));
687:     for (const sheet of this.level.sheets) {
688:       const b = sheet.bounds;
689:       addPoint(b.minX, sheet.y - 0.5, b.minZ);
690:       addPoint(b.maxX, sheet.y + 0.5, b.maxZ);
691:       addPoint(b.minX, sheet.y + 3.4, b.minZ);
692:     }
693:     for (const p of this.level.platforms || []) {
694:       addPoint(p.x - p.w / 2, p.top, p.z - p.d / 2);
695:       addPoint(p.x + p.w / 2, p.top + 1.2, p.z + p.d / 2);
696:     }
697:     for (const s of this.level.stars || []) {
698:       if (s.sheet === undefined) addPoint(s.x, s.y, s.z);
699:     }
700:     if (this.level.exit && this.level.exit.sheet === undefined) addPoint(this.level.exit.x, this.level.exit.y, this.level.exit.z);
701:     if (this.player) addPoint(this.player.pos.x, this.player.pos.y + 1, this.player.pos.z);
702:     return box;
703:   }
704: 
705:   _frameLevel () {
706:     const box = this.levelBounds || this._roughBounds();
707:     const center = box.getCenter(new THREE.Vector3());
708:     const dir = new THREE.Vector3(0.86, 1.02, 1.15).normalize();
709:     const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 100);
710:     camera.position.copy(center).addScaledVector(dir, 30);
711:     camera.lookAt(center);
712:     camera.updateMatrixWorld(true);
713:     const inv = new THREE.Matrix4().copy(camera.matrixWorldInverse);
714:     let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
715:     const corners = [
716:       [box.min.x, box.min.y, box.min.z], [box.min.x, box.min.y, box.max.z],
717:       [box.min.x, box.max.y, box.min.z], [box.min.x, box.max.y, box.max.z],
718:       [box.max.x, box.min.y, box.min.z], [box.max.x, box.min.y, box.max.z],
719:       [box.max.x, box.max.y, box.min.z], [box.max.x, box.max.y, box.max.z],
720:     ];
721:     for (const c of corners) {
722:       TMP.set(c[0], c[1], c[2]).applyMatrix4(inv);
723:       minX = Math.min(minX, TMP.x); maxX = Math.max(maxX, TMP.x);
724:       minY = Math.min(minY, TMP.y); maxY = Math.max(maxY, TMP.y);
725:     }
726:     const aspect = this.width / this.height;
727:     let hw = (maxX - minX) / 2 + 0.65;
728:     let hh = (maxY - minY) / 2 + 0.65;
729:     if (hw / hh < aspect) hw = hh * aspect; else hh = hw / aspect;
730:     camera.left = -hw;
731:     camera.right = hw;
732:     camera.top = hh;
733:     camera.bottom = -hh;
734:     camera.near = 0.1;
735:     camera.far = 100;
736:     camera.updateProjectionMatrix();
737:     this.camera = camera;
738:     this.cameraBase = { hw, hh, center: center.clone(), dir: dir.clone() };
739:     this.camera.zoom = 1;
740:   }
