745:   _bindInput () {
746:     this.canvas.addEventListener('pointerdown', e => this._onPointerDown(e));
747:     this.canvas.addEventListener('pointermove', e => this._onPointerMove(e));
748:     this.canvas.addEventListener('pointerup', e => this._onPointerUp(e));
