750:     this.canvas.addEventListener('contextmenu', e => e.preventDefault());
751:     window.addEventListener('keydown', e => {
752:       if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) e.preventDefault();
753:       this.keys.add(e.key.toLowerCase());
754:       if (e.key === 'Escape') this.emit('keyescape');
755:       if (e.key.toLowerCase() === 'r' && this.mode === 'game' && !this.paused) this.restart();
756:       if (e.key.toLowerCase() === 'h' && this.mode === 'game' && !this.paused) this.nextHint();
757:     });
758:     window.addEventListener('keyup', e => this.keys.delete(e.key.toLowerCase()));
