768:   _ndc (e) {
769:     const r = this.canvas.getBoundingClientRect();
770:     return { x: ((e.clientX - r.left) / r.width) * 2 - 1, y: -((e.clientY - r.top) / r.height) * 2 + 1 };
771:   }
