773:   _hitPaper (e) {
774:     if (!this.camera) return null;
775:     const n = this._ndc(e);
776:     this.raycaster.setFromCamera(n, this.camera);
777:     const hits = this.raycaster.intersectObjects(this.paperMeshes, false);
778:     return hits.length ? hits[0] : null;
779:   }
