781:   _pointerOnPlane (e, panel) {
782:     const n = this._ndc(e);
783:     this.raycaster.setFromCamera(n, this.camera);
784:     const plane = new THREE.Plane(UP, -(panel.group.position.y + 0.07));
785:     const point = new THREE.Vector3();
786:     if (!this.raycaster.ray.intersectPlane(plane, point)) return null;
787:     return point;
788:   }
