790:   _onPointerDown (e) {
791:     if (this.mode !== 'game' || this.paused || this.completed || this.trappedTimer > 0) return;
792:     if (this.pointerState) return;
793:     if (e.button !== undefined && e.button !== 0) return;
794:     const hit = this._hitPaper(e);
795:     if (!hit) {
796:       if (this.pendingCrease) this.clearCrease();
797:       return;
798:     }
799:     const panel = hit.object.userData.panel;
800:     if (!panel) return;
801:     this.canvas.setPointerCapture?.(e.pointerId);
802:     const state = {
803:       id: e.pointerId,
804:       start: { x: e.clientX, y: e.clientY },
805:       current: { x: e.clientX, y: e.clientY },
806:       panel,
807:       mode: null,
808:       startAngle: 0,
809:       startPoint: null,
810:     };
811: 
812:     // adjusting a flap that is already folded
