1331:       p.root.visible = p.invuln <= 0 || Math.floor(p.invuln * 14) % 2 === 0;
1332:     }
1333: 
1334:     if (p.falling) {
1335:       p.vel.y -= 16 * dt;
1336:       p.pos.y += p.vel.y * dt;
1337:       // air control
1338:       if (mag > 0.05) {
1339:         const mv = this._moveVector(ix, iy);
1340:         p.pos.x += mv.x * 1.4 * dt;
1341:         p.pos.z += mv.z * 1.4 * dt;
1342:       }
1343:       const g = this._groundAt(p.pos.x, p.pos.z, p.pos.y + 1.8);
1344:       if (g && p.pos.y <= g.y + 0.02) {
1345:         p.pos.y = g.y;
1346:         p.groundY = g.y;
1347:         p.vel.y = 0;
1348:         p.falling = false;
1349:         p.grounded = true;
1350:         p.squash = 0.14;
1351:         p.panel = g.mesh?.userData?.panel || null;
1352:         this.sound.step();
1353:         this._dustPuff(p.pos);
1354:       }
1355:       if (p.pos.y < -6) this._respawn(true);
1356:     } else if (active && mag > 0.08) {
1357:       const mv = this._moveVector(ix, iy);
1358:       const speed = 3.1 * Math.min(1, mag);
1359:       this._tryMove(mv.x * speed * dt, mv.z * speed * dt);
1360:       p.targetFacing = Math.atan2(mv.x, mv.z);
1361:       p.phase += dt * speed * 3.1;
1362:       p.stepTimer -= dt;
1363:       if (p.stepTimer <= 0) {
1364:         p.stepTimer = 0.34;
1365:         if (p.grounded) this.sound.step();
1366:       }
1367:       // if walked off an edge, fall
1368:       const g = this._groundAt(p.pos.x, p.pos.z, p.pos.y + 1.0);
1369:       if (!g || g.y < p.pos.y - 0.5) {
1370:         p.falling = true;
1371:         p.grounded = false;
1372:         p.vel.y = 0;
1373:       } else {
1374:         p.pos.y += (g.y - p.pos.y) * 0.55;
1375:         p.groundY = g.y;
1376:         p.panel = g.mesh?.userData?.panel || null;
1377:       }
1378:     } else {
1379:       p.phase += dt * 1.8;
1380:     }
1381: 
1382:     // gentle facing interpolation
1383:     if (p.root) {
1384:       let d = p.targetFacing - p.facing;
1385:       while (d > Math.PI) d -= Math.PI * 2;
1386:       while (d < -Math.PI) d += Math.PI * 2;
1387:       p.facing += d * Math.min(1, dt * 11);
1388:       p.root.rotation.y = p.facing;
1389:       p.root.position.copy(p.pos);
1390:       p.squash = Math.max(0, p.squash - dt * 1.4);
1391:       const walking = mag > 0.08 && p.grounded && !p.falling && !this.pointerState;
1392:       const bob = walking ? Math.abs(Math.sin(p.phase * 2)) * 0.035 : Math.sin(p.phase) * 0.012;
1393:       p.root.position.y += bob - p.squash * 0.14;
1394:       const model = p.root.userData.model;
1395:       if (model) {
1396:         model.scale.y = 1 - p.squash * 0.5;
1397:         model.scale.x = model.scale.z = 1 + p.squash * 0.25;
1398:         const legs = p.root.userData.legs || [];
1399:         legs.forEach((leg, i) => {
1400:           const dir = i < 2 ? 1 : -1;
1401:           leg.rotation.x = walking ? Math.sin(p.phase * 2 + (i % 2) * Math.PI) * 0.5 * dir : Math.sin(p.phase + i) * 0.035;
1402:         });
1403:         const tail = p.root.userData.tail;
1404:         if (tail) tail.rotation.z = Math.sin(p.phase * 1.5) * 0.12;
1405:         const head = p.root.userData.head;
1406:         if (head) {
1407:           head.rotation.x = walking ? Math.sin(p.phase * 2) * 0.025 : Math.sin(p.phase * 0.7) * 0.03;
1408:           const ear = p.root.userData.ears?.[0];
1409:           const ear2 = p.root.userData.ears?.[1];
1410:           if (ear) ear.rotation.x = Math.sin(p.phase * 2.2) * 0.05;
1411:           if (ear2) ear2.rotation.x = Math.sin(p.phase * 2.2 + 1) * 0.05;
1412:         }
1413:       }
1414:     }
1415: 
1416:     // star collection
1417:     for (const star of this.stars) {
1418:       if (star.collected) continue;
1419:       this._positionStar(star);
1420:       const dx = star.group.position.x - p.pos.x;
1421:       const dz = star.group.position.z - p.pos.z;
1422:       const dy = star.group.position.y - (p.pos.y + 0.5);
1423:       if (dx * dx + dz * dz < 0.46 && Math.abs(dy) < 0.9) this._collectStar(star);
1424:     }
1425: 
1426:     // exit
1427:     if (this.exit && !this.completed) {
1428:       if (this.exit.anchor) this.exit.anchor.getWorldPosition(TMP);
1429:       else TMP.copy(this.exit.group.position);
1430:       const dx = TMP.x - p.pos.x;
1431:       const dz = TMP.z - p.pos.z;
1432:       const dy = TMP.y - (p.pos.y + 0.4);
1433:       if (dx * dx + dz * dz < 0.46 && Math.abs(dy) < 1.25) this._completeLevel();
1434:     }
1435: 
1436:     // enemies
1437:     for (const e of this.enemies) {
1438:       const range = e.range;
1439:       const span = range[1] - range[0];
1440:       const t = this.elapsed * e.speed + e.phase;
1441:       const along = range[0] + (span * (0.5 + 0.5 * Math.sin(t)));
1442:       if (e.axis === 'x') e.obj.position.x = along; else e.obj.position.z = along;
1443:       e.obj.rotation.y = (e.axis === 'x' ? (Math.cos(t) > 0 ? Math.PI / 2 : -Math.PI / 2) : (Math.cos(t) > 0 ? 0 : Math.PI));
1444:       const legs = e.obj.userData.legs || [];
1445:       legs.forEach((leg, i) => { leg.rotation.x = Math.sin(this.elapsed * 9 + i) * 0.35; });
1446:       if (p.invuln <= 0 && this.trappedTimer <= 0) {
1447:         const ex = e.obj.position.x - p.pos.x;
1448:         const ez = e.obj.position.z - p.pos.z;
1449:         const ey = e.y - p.pos.y;
1450:         if (Math.hypot(ex, ez) < 0.55 && Math.abs(ey) < 0.8) {
1451:           this._hitByEnemy();
1452:         }
1453:       }
1454:     }
1455:   }
1456: 
1457:   _moveVector (ix, iy) {
1458:     const cam = this.camera || this.menuCamera;
1459:     const forward = new THREE.Vector3();
1460:     cam.getWorldDirection(forward);
1461:     forward.y = 0;
1462:     if (forward.lengthSq() < 0.001) forward.set(0, 0, -1);
1463:     forward.normalize();
1464:     const right = new THREE.Vector3().crossVectors(forward, UP).normalize();
1465:     const v = new THREE.Vector3().addScaledVector(forward, iy).addScaledVector(right, ix);
1466:     if (v.lengthSq() > 1) v.normalize();
1467:     return v;
1468:   }
