1470:   _positionStar (star) {
1471:     if (star.collected) return;
1472:     let base;
1473:     if (star.anchor) {
1474:       star.anchor.getWorldPosition(TMP);
1475:       base = TMP;
1476:     } else {
1477:       base = TMP.set(star.group.position.x, star.baseY, star.group.position.z);
1478:     }
1479:     const bob = Math.sin(this.elapsed * 1.7 + star.seed) * 0.08;
1480:     star.group.position.set(base.x, base.y + bob, base.z);
1481:     if (star.group.userData.spin) {
1482:       star.group.userData.spin.rotation.y = this.elapsed * 1.1 + star.spin;
1483:       star.group.userData.spin.rotation.z = Math.sin(this.elapsed * 0.8 + star.spin) * 0.12;
1484:     }
1485:     if (star.group.userData.glow) {
1486:       star.group.userData.glow.material.opacity = 0.45 + Math.sin(this.elapsed * 2.2 + star.seed) * 0.15;
1487:     }
1488:   }
1489: 
1490:   _collectStar (star) {
1491:     star.collected = true;
1492:     this.starCount++;
1493:     this.sound.star();
1494:     this._burst(star.group.position, 0xffd57a, 18);
1495:     star.group.visible = false;
1496:     this.emit('star', { count: this.starCount, total: this.totalStars });
1497:     this.emit('hud', { stars: this.starCount, total: this.totalStars });
1498:     this.emit('toast', { text: 'Golden origami star found', duration: 2200, star: true });
1499:     if (this.level.tutorial) {
1500:       this.emit('tutorial', { title: 'A hidden star', text: 'Stars unlock new paper souls. Find them all.' });
1501:     }
1502:     this.emit('haptic', 'star');
1503:   }
