1505:   _burst (pos, color = 0xffd57a, count = 24) {
1506:     const geo = new THREE.BufferGeometry();
1507:     const arr = new Float32Array(count * 3);
1508:     const vel = [];
1509:     for (let i = 0; i < count; i++) {
1510:       arr[i * 3] = pos.x; arr[i * 3 + 1] = pos.y; arr[i * 3 + 2] = pos.z;
1511:       const a = Math.random() * Math.PI * 2;
1512:       const b = Math.random() * Math.PI;
1513:       const s = 0.7 + Math.random() * 1.7;
1514:       vel.push(new THREE.Vector3(Math.sin(b) * Math.cos(a) * s, Math.cos(b) * s, Math.sin(b) * Math.sin(a) * s));
1515:     }
1516:     geo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
1517:     const mat = new THREE.PointsMaterial({
1518:       color, size: 0.11, map: P.glowTexture(), transparent: true, opacity: 1,
1519:       blending: THREE.AdditiveBlending, depthWrite: false,
1520:     });
1521:     const points = new THREE.Points(geo, mat);
1522:     this.worldGroup.add(points);
1523:     this.sparkBursts.push({ obj: points, life: 1.25, max: 1.25, vel, gravity: true });
1524:   }
1525: 
1526:   _dustPuff (pos) {
1527:     const count = this.isMobile ? 5 : 9;
1528:     const geo = new THREE.BufferGeometry();
1529:     const arr = new Float32Array(count * 3);
1530:     for (let i = 0; i < count; i++) {
1531:       arr[i * 3] = pos.x + (Math.random() - 0.5) * 0.3;
1532:       arr[i * 3 + 1] = pos.y + 0.04;
1533:       arr[i * 3 + 2] = pos.z + (Math.random() - 0.5) * 0.3;
1534:     }
1535:     geo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
1536:     const mat = new THREE.PointsMaterial({ color: 0xd8c7a6, size: 0.07, transparent: true, opacity: 0.55, depthWrite: false });
1537:     const p = new THREE.Points(geo, mat);
1538:     this.worldGroup.add(p);
1539:     this.sparkBursts.push({ obj: p, life: 0.5, max: 0.5, vel: null, rise: true });
1540:   }
