1603:   showHint (index = 0, opts = {}) {
1604:     if (!this.level) return;
1605:     const hints = this.level.hints || [];
1606:     if (!hints.length) return;
1607:     const hint = hints[index % hints.length];
1608:     this.hintIndex = index;
1609:     const panel = this.sheetPanels[hint.sheet];
1610:     if (!panel || !panel.foldable || panel.folded || panel.fold) {
1611:       // find next usable hint
1612:       if (!opts.noCycle && hints.length > 1) {
1613:         for (let i = 1; i < hints.length; i++) {
1614:           const p2 = this.sheetPanels[hints[(index + i) % hints.length].sheet];
1615:           if (p2 && p2.foldable && !p2.folded && !p2.fold) {
1616:             this.showHint(index + i, { ...opts, noCycle: false });
1617:             return;
1618:           }
1619:         }
1620:       }
1621:       this.emit('toast', { text: 'That fold is already made. Try another sheet.', duration: 1800 });
1622:       return;
1623:     }
1624:     this._hideHint();
1625:     const len = hint.axis === 'x' ? panel.bounds.maxZ - panel.bounds.minZ : panel.bounds.maxX - panel.bounds.minX;
1626:     const guide = P.makeCreaseLine(len, hint.axis, opts.auto ? 0xf4c766 : 0xddaa4d);
1627:     if (hint.axis === 'x') guide.position.set(hint.coord, panel.group.position.y + 0.13, (panel.bounds.minZ + panel.bounds.maxZ) / 2);
1628:     else guide.position.set((panel.bounds.minX + panel.bounds.maxX) / 2, panel.group.position.y + 0.13, hint.coord);
1629:     const glint = new THREE.Sprite(new THREE.SpriteMaterial({
1630:       map: P.glowTexture(), color: 0xffd986, transparent: true, opacity: 0.85,
1631:       blending: THREE.AdditiveBlending, depthWrite: false,
1632:     }));
1633:     glint.scale.setScalar(0.8);
1634:     guide.add(glint);
1635:     guide.userData.glint = glint;
1636:     guide.userData.len = len;
1637:     this.worldGroup.add(guide);
1638:     this.hintGuide = guide;
1639:     this.emit('hint', { text: hint.text, index, ...hint });
1640:     this.emit('toast', { text: `Hint · ${hint.text}`, duration: 4200 });
1641:   }
