1675:   _updateMenu (dt) {
1676:     if (!this.menuScene) return;
1677:     const t = this.elapsed;
1678:     if (this.menuFox) {
1679:       const fox = this.menuFox;
1680:       fox.userData.model.position.y = Math.sin(t * 1.4) * 0.012;
1681:       fox.userData.head.rotation.y = Math.sin(t * 0.6) * 0.18;
1682:       fox.userData.head.rotation.x = Math.sin(t * 0.9) * 0.04;
1683:       fox.userData.tail.rotation.z = Math.sin(t * 1.6) * 0.15;
1684:       fox.userData.ears.forEach((ear, i) => { ear.rotation.x = Math.sin(t * 1.8 + i) * 0.06; });
1685:     }
1686:     if (this.menuStar) {
1687:       this.menuStar.position.y = 1.85 + Math.sin(t * 1.2) * 0.12;
1688:       this.menuStar.userData.spin.rotation.y = t * 0.9;
1689:       this.menuStar.userData.glow.material.opacity = 0.45 + Math.sin(t * 2) * 0.12;
1690:     }
1691:     if (this.menuSeal) {
1692:       this.menuSeal.userData.diamond.rotation.y = t * 0.6;
1693:       this.menuSeal.userData.diamond.position.y = 0.13 + Math.sin(t * 1.4) * 0.05;
1694:     }
1695:     for (const f of this.menuFloaters || []) {
1696:       f.isl.position.y = f.baseY + Math.sin(t * 0.6 + f.phase) * 0.09;
1697:       f.prop.position.y = f.isl.position.y;
1698:     }
1699:     for (const c of this.menuCranes || []) {
1700:       const a = t * c.speed + c.phase;
1701:       c.obj.position.x = Math.cos(a) * c.radius;
1702:       c.obj.position.z = Math.sin(a) * c.radius - 0.6;
1703:       c.obj.position.y = 2.0 + Math.sin(a * 1.4) * 0.2;
1704:       c.obj.rotation.y = -a + Math.PI / 2;
1705:       const wings = c.obj.userData.wings || [];
1706:       wings.forEach((w, i) => { w.rotation.z = Math.sin(t * 2.4 + i) * 0.12; });
1707:     }
1708:     for (const c of this.menuClouds || []) {
1709:       c.obj.position.x = c.baseX + Math.sin(t * c.speed + c.phase) * 0.6;
1710:     }
1711:     if (this.menuMotes) {
1712:       const pos = this.menuMotes.geometry.attributes.position;
1713:       const base = this.menuMotes.userData.base;
1714:       for (let i = 0; i < pos.count; i++) {
1715:         pos.array[i * 3 + 1] = base[i * 3 + 1] + Math.sin(t * 0.4 + i) * 0.4;
1716:       }
1717:       pos.needsUpdate = true;
1718:     }
1719:     if (this.menuMountain) this.menuMountain.rotation.y = Math.sin(t * 0.05) * 0.02;
1720:     this._placeMenuCamera();
1721:     const cam = this.menuCamera;
1722:     cam.position.x += Math.sin(t * 0.15) * 0.25;
1723:     cam.position.z += Math.cos(t * 0.13) * 0.18;
1724:     cam.lookAt(this.menuTarget.x + Math.sin(t * 0.1) * 0.2, this.menuTarget.y, this.menuTarget.z);
1725:   }
