1727:   _updateGame (dt) {
1728:     if (!this.scene) return;
1729:     if (this.paused) {
1730:       this._updateAmbient(dt);
1731:       return;
1732:     }
1733:     if (this.trappedTimer > 0) {
1734:       this.trappedTimer -= dt;
1735:       this.freeze = Math.max(0, this.freeze - dt);
1736:       if (this.trappedTimer <= 0) {
1737:         this.restart();
1738:       }
1739:       this._updateAmbient(dt);
1740:       return;
1741:     }
1742:     if (this.completed) {
1743:       this._updateAmbient(dt);
1744:       this.completedTimer -= dt;
1745:       if (this.completedTimer <= 0 && !this._completeSent) {
1746:         this._completeSent = true;
1747:         this.emit('levelcomplete', this.completeStats);
1748:       }
1749:       return;
1750:     }
1751:     this._completeSent = false;
1752:     this.time += dt;
1753:     if (this.freeze > 0) this.freeze -= dt;
1754: 
1755:     if (this.fold && this.fold.animating) {
1756:       const f = this.fold;
1757:       f.animT += dt / 0.2;
1758:       const k = Math.min(1, f.animT);
1759:       const a = f.animFrom + (f.animTo - f.animFrom) * easeInOut(k);
1760:       this._setFoldAngleRaw(f, a);
1761:       this.emit('foldchange', { angle: a });
1762:       if (k >= 1) {
1763:         f.animating = false;
1764:         f.angle = f.animTo;
1765:         this._setFoldAngleRaw(f, f.animTo);
1766:         this._onFoldSettled(f);
1767:       }
1768:     }
1769: 
1770:     this._updatePlayer(dt);
1771:     this._updateAmbient(dt);
1772:     this._updateHint(dt);
1773:     this._updateBursts(dt);
1774: 
1775:     // invulnerability flash resets
1776:     if (this.player) {
1777:       this.player.invuln = Math.max(0, this.player.invuln - dt);
1778:     }
1779:   }
1780: 
1781:   _updateAmbient (dt) {
1782:     const t = this.elapsed;
1783:     for (const m of this.motes) {
1784:       const pos = m.obj.geometry.attributes.position;
1785:       const base = m.base;
1786:       const speed = m.speed || 0.2;
