228:     quad([x0, yt, z0], [x0, yt, z1], [x1, yt, z1], [x1, yt, z0], [0, 1, 0], white,
229:       p => [p[0] * uvScale, p[2] * uvScale]);
230:     // bottom (-Y)
231:     quad([x0, yb, z1], [x0, yb, z0], [x1, yb, z0], [x1, yb, z1], [0, -1, 0], bottomCol,
