239:     // +Z
240:     quad([x0, yb, z1], [x1, yb, z1], [x1, yt, z1], [x0, yt, z1], [0, 0, 1], sideCol,
241:       p => [p[0] * uvScale, p[1] * uvScale]);
242:     // -Z
243:     quad([x1, yb, z0], [x0, yb, z0], [x0, yt, z0], [x1, yt, z0], [0, 0, -1], sideCol,
