295:   const inst = new THREE.InstancedMesh(geo, mat, dashCount);
296:   const m = new THREE.Matrix4();
297:   const q = new THREE.Quaternion();
298:   const scale = new THREE.Vector3(1, 1, 1);
299:   for (let i = 0; i < dashCount; i++) {
300:     const p = -length / 2 + (i + 0.5) * (length / dashCount);
301:     m.compose(new THREE.Vector3(axis === 'x' ? 0 : p, 0, axis === 'x' ? p : 0), q, scale);
302:     inst.setMatrixAt(i, m);
303:   }
304:   inst.rotation.x = -Math.PI / 2;
305:   group.add(inst);
306:   const glow = new THREE.Mesh(
307:     new THREE.PlaneGeometry(axis === 'x' ? 0.55 : length, axis === 'x' ? length : 0.55),
308:     new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.09, side: THREE.DoubleSide, depthWrite: false })
309:   );
310:   glow.rotation.x = -Math.PI / 2;
311:   group.add(glow);
312:   group.userData.inst = inst;
313:   group.userData.glow = glow;
314:   return group;
315: }
