317: export function makeHinge (axis, length, y) {
318:   const g = new THREE.Group();
319:   const gold = colorMat('#c99a44', { metalness: 0.45, roughness: 0.38 });
320:   const cyl = new THREE.CylinderGeometry(0.055, 0.055, 0.28, 8);
321:   const ring = new THREE.TorusGeometry(0.105, 0.025, 6, 14);
322:   for (let i = 0; i < 3; i++) {
323:     const c = new THREE.Mesh(cyl, gold);
324:     const r = new THREE.Mesh(ring, gold);
325:     const t = -length / 2 + 0.35 + i * (length - 0.7) / 2;
326:     if (axis === 'x') {
327:       c.rotation.x = Math.PI / 2;
328:       c.position.set(0, 0, t);
329:       r.rotation.y = Math.PI / 2;
330:       r.position.set(0, 0.07, t);
331:     } else {
332:       c.rotation.z = Math.PI / 2;
333:       c.position.set(t, 0, 0);
334:       r.rotation.x = Math.PI / 2;
335:       r.position.set(t, 0.07, 0);
336:     }
337:     c.castShadow = true;
338:     g.add(c, r);
339:   }
340:   g.position.y = y;
341:   return g;
342: }
