347: function starShape (outer = 0.34, inner = 0.15) {
348:   const shape = new THREE.Shape();
349:   for (let i = 0; i < 10; i++) {
350:     const r = i % 2 === 0 ? outer : inner;
351:     const a = -Math.PI / 2 + i * Math.PI / 5;
352:     const x = Math.cos(a) * r;
353:     const y = Math.sin(a) * r;
354:     if (i === 0) shape.moveTo(x, y); else shape.lineTo(x, y);
355:   }
356:   shape.closePath();
357:   return shape;
358: }
